  `house_mer` SMALLINT NULL, `house_jup` SMALLINT NULL, `house_ven` SMALLINT NULL, `house_sat` SMALLINT NULL,
  `house_rah` SMALLINT NULL, `house_ket` SMALLINT NULL,
