  PRIMARY KEY (`native_id`),
  KEY `idx_native_name` (`native_name`),
  KEY `idx_native_birth_date` (`birth_date`),
  KEY `idx_native_place` (`birth_place`),
  KEY `idx_native_serial` (`serial_no`)
